mapper.select:
SELECT id, title, description, total_score, status, created_by, created_at, updated_at
FROM paper
WHERE id = #{id}

mapper.update:
UPDATE paper
SET title       = #{title},
    description = #{description},
    total_score = #{totalScore}
WHERE id = #{id}

UPDATE paper
SET status = #{status}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE paper_question
SET question_snapshot = #{snapshot}
WHERE paper_id = #{paperId}
  AND question_id = #{questionId}

mapper.select:
SELECT paper_id AS paperId, COUNT(*) AS questionCount FROM paper_question WHERE paper_id IN
#{paperId}
GROUP BY paper_id

SELECT COUNT(*)
FROM exam
WHERE paper_id = #{paperId}
